// Generated by scaffold-page-from-story from user_stories/ADM-01-dashboard.yaml
// Story: US-ADM-01-DASHBOARD
// Role:  admin
// Feature: Console dashboard
// Goal: As an operator I can open the dashboard and see published courses, students, recent orders and revenue so that I know the state of the product without running a query.
//
// PRIMARY deterministic page (v128): generated BEFORE convert-pages. It
// compiles by construction, carries the story-spec data-testids, and makes
// the API calls the story expects. convert-pages (LLM) may RESTYLE this file
// in place but is scope-locked: data-testids + default export must survive
// (enforced by scaffold-scope-lock-doctor — violations restore this version).
//
// Restyled to mirror design/html/admin/ADM-01-dashboard.html. Shared chrome
// (sidebar + topbar) is owned by AdminLayout and is intentionally NOT emitted
// here — only the page's unique content region is rendered.

import { useEffect, useState } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';

import { useAppDispatch } from '~/hooks/useAppDispatch';
import { getStats, listOrders } from '~/services/httpServices/adminConsoleService';

import { order_status } from '~/enums/order-status.enum';

import { cn } from '~/lib/utils';
import type { DashboardOrderRow, DashboardStats, OrdersListResponse } from '~/types/view-models';

const STATUS_STYLES: Record<number, string> = {
  [order_status.PAID]: 'bg-emerald-100 text-emerald-700',
  [order_status.PENDING]: 'bg-amber-100 text-amber-700',
  [order_status.CANCELLED]: 'bg-rose-100 text-rose-700',
  [order_status.REFUNDED]: 'bg-muted text-muted-foreground',
};

const STATUS_LABELS: Record<number, string> = {
  [order_status.PAID]: 'Paid',
  [order_status.PENDING]: 'Pending',
  [order_status.CANCELLED]: 'Cancelled',
  [order_status.REFUNDED]: 'Refunded',
};

const CARD = 'rounded-[12px] border border-border bg-card p-6 shadow-sm';

function formatCount(value?: number | null): string {
  return Number(value ?? 0).toLocaleString();
}

function formatCurrency(value?: number | null): string {
  return Number(value ?? 0).toLocaleString(undefined, {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  });
}

export default function AdminDashboardPage() {
  const { t } = useTranslation();
  const dispatch = useAppDispatch();

  // Admin-only console. Access is enforced by the route guard (auth:admin) on
  // AdminLayout; this page assumes the ADMIN role and shows operator-wide data.
  const role = 'admin' as const;
  const isAdmin = role === 'admin';

  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [statsLoading, setStatsLoading] = useState<boolean>(true);
  const [statsError, setStatsError] = useState<string | null>(null);

  const [orders, setOrders] = useState<DashboardOrderRow[]>([]);
  const [ordersLoading, setOrdersLoading] = useState<boolean>(true);
  const [ordersError, setOrdersError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setStatsLoading(true);
    setStatsError(null);
    dispatch(getStats(undefined))
      .unwrap()
      .then((res) => {
        if (!cancelled) setStats(res as DashboardStats);
      })
      .catch((e: unknown) => {
        if (!cancelled) setStatsError(e instanceof Error ? e.message : 'Failed to load');
      })
      .finally(() => {
        if (!cancelled) setStatsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [dispatch]);

  useEffect(() => {
    let cancelled = false;
    setOrdersLoading(true);
    setOrdersError(null);
    dispatch(listOrders(undefined))
      .unwrap()
      .then((res) => {
        if (cancelled) return;
        const data = res as OrdersListResponse;
        setOrders(Array.isArray(data.items) ? data.items : []);
      })
      .catch((e: unknown) => {
        if (!cancelled) setOrdersError(e instanceof Error ? e.message : 'Failed to load');
      })
      .finally(() => {
        if (!cancelled) setOrdersLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [dispatch]);

  const kpis = [
    {
      key: 'published-courses',
      label: t('admin.dashboard.kpi.publishedCourses', 'Published courses'),
      value: formatCount(stats?.publishedCourses),
    },
    {
      key: 'students',
      label: t('admin.dashboard.kpi.students', 'Students'),
      value: formatCount(stats?.students),
    },
    {
      key: 'paid-orders',
      label: t('admin.dashboard.kpi.paidOrders', 'Paid orders (30d)'),
      value: formatCount(stats?.paidOrders30d),
    },
    {
      key: 'revenue',
      label: t('admin.dashboard.kpi.revenue', 'Revenue (30d)'),
      value: formatCurrency(stats?.revenue30d),
    },
  ];

  const recentOrders = orders.slice(0, 5);
  const topCourses = stats?.topCourses ?? [];

  return (
    <div
      className="flex flex-col gap-8 p-6"
      data-testid="adm-01-dashboard-page"
      data-role={role}
      data-is-admin={isAdmin ? 'true' : 'false'}
    >
      <div className="flex items-center gap-2 text-[14px] text-muted-foreground">
        <Link to="/" className="hover:text-foreground" data-testid="adm-01-dashboard-home-link">
          {t('admin.dashboard.home', 'Home')}
        </Link>
        <span aria-hidden="true">/</span>
        <span className="font-medium text-foreground">{t('admin.dashboard.title', 'Dashboard')}</span>
      </div>
      <h1 className="sr-only" data-testid="adm-01-dashboard-heading">
        {t('admin.dashboard.title', 'Dashboard')}
      </h1>

      <div className="flex flex-col gap-8" data-testid="adm-01-dashboard-main">
        {/* KPIs — GET /api/admin/stats */}
        <section data-testid="adm-01-dashboard-ac-1" aria-label={t('admin.dashboard.metrics', 'Key metrics')}>
          {statsLoading && (
            <div
              className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4"
              data-testid="adm-01-dashboard-ac-1-loading"
            >
              {[0, 1, 2, 3].map((i) => (
                <div key={i} className={cn(CARD, 'flex flex-col gap-2')}>
                  <span className="h-[34px] w-20 animate-pulse rounded bg-muted" />
                  <span className="h-[18px] w-28 animate-pulse rounded bg-muted" />
                </div>
              ))}
            </div>
          )}
          {statsError && (
            <p className="text-[14px] text-destructive" data-testid="adm-01-dashboard-ac-1-error">
              {t('admin.dashboard.metricsError', 'Unable to load metrics')}
            </p>
          )}
          {!statsLoading && !statsError && (
            <div
              className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4"
              data-testid="adm-01-dashboard-ac-1-detail"
            >
              {kpis.map((kpi) => (
                <div
                  key={kpi.key}
                  className={cn(CARD, 'flex flex-col gap-2')}
                  data-testid={`adm-01-dashboard-kpi-${kpi.key}`}
                >
                  <span className="text-[28px] font-bold leading-tight text-foreground">{kpi.value}</span>
                  <span className="text-[14px] text-muted-foreground">{kpi.label}</span>
                </div>
              ))}
            </div>
          )}
        </section>

        <div className="grid grid-cols-1 gap-6 lg:grid-cols-[3fr_2fr]">
          {/* Recent orders — GET /api/admin/orders */}
          <section className={cn(CARD, 'flex flex-col gap-4')} data-testid="adm-01-dashboard-ac-2">
            <div className="flex items-center justify-between gap-4">
              <h2 className="text-[20px] font-semibold text-foreground">
                {t('admin.dashboard.recentOrders', 'Recent orders')}
              </h2>
              <Link
                to="/admin/orders"
                className="text-[14px] font-semibold text-primary hover:underline"
                data-testid="adm-01-dashboard-all-orders"
              >
                {t('admin.dashboard.allOrders', 'All orders')}
              </Link>
            </div>

            {ordersLoading && (
              <p className="text-[14px] text-muted-foreground" data-testid="adm-01-dashboard-ac-2-loading">
                {t('common.loading', 'Loading…')}
              </p>
            )}
            {ordersError && (
              <p className="text-[14px] text-destructive" data-testid="adm-01-dashboard-ac-2-error">
                {t('admin.dashboard.ordersError', 'Unable to load orders')}
              </p>
            )}
            {!ordersLoading && !ordersError && recentOrders.length === 0 && (
              <p className="text-[14px] text-muted-foreground" data-testid="adm-01-dashboard-ac-2-empty">
                {t('admin.dashboard.ordersEmpty', 'No orders yet')}
              </p>
            )}
            {!ordersLoading && !ordersError && recentOrders.length > 0 && (
              <div className="overflow-x-auto">
                <table className="w-full text-left text-[14px]" data-testid="adm-01-dashboard-ac-2-kpis">
                  <thead>
                    <tr className="border-b border-border text-muted-foreground">
                      <th className="py-2 pr-4 font-medium">{t('admin.dashboard.col.order', 'Order')}</th>
                      <th className="py-2 pr-4 font-medium">{t('admin.dashboard.col.student', 'Student')}</th>
                      <th className="py-2 pr-4 text-right font-medium">{t('admin.dashboard.col.total', 'Total')}</th>
                      <th className="py-2 font-medium">{t('admin.dashboard.col.status', 'Status')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentOrders.map((o) => {
                      const status = o.status ?? -1;
                      return (
                        <tr
                          key={o.id}
                          className="border-b border-border/60 last:border-0"
                          data-testid={`adm-01-dashboard-ac-2-kpi-${o.id}`}
                        >
                          <td className="py-3 pr-4 font-medium text-foreground">{o.orderNumber}</td>
                          <td className="py-3 pr-4 text-foreground">{o.student ?? ''}</td>
                          <td className="py-3 pr-4 text-right tabular-nums text-foreground">
                            {formatCurrency(o.total)}
                          </td>
                          <td className="py-3">
                            <span
                              className={cn(
                                'inline-flex items-center rounded-full px-2.5 py-0.5 text-[12px] font-medium',
                                STATUS_STYLES[status] ?? 'bg-muted text-muted-foreground',
                              )}
                            >
                              {t(`order.status.${status}`, STATUS_LABELS[status] ?? '—')}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </section>

          {/* Top courses — GET /api/admin/stats */}
          <section className={cn(CARD, 'flex flex-col gap-4')} data-testid="adm-01-dashboard-ac-3">
            <h2 className="text-[20px] font-semibold text-foreground">
              {t('admin.dashboard.topCourses', 'Top courses')}
            </h2>
            {statsLoading && (
              <p className="text-[14px] text-muted-foreground" data-testid="adm-01-dashboard-ac-3-loading">
                {t('common.loading', 'Loading…')}
              </p>
            )}
            {statsError && (
              <p className="text-[14px] text-destructive" data-testid="adm-01-dashboard-ac-3-error">
                {t('admin.dashboard.topCoursesError', 'Unable to load courses')}
              </p>
            )}
            {!statsLoading && !statsError && topCourses.length === 0 && (
              <p className="text-[14px] text-muted-foreground" data-testid="adm-01-dashboard-ac-3-empty">
                {t('admin.dashboard.topCoursesEmpty', 'No courses yet')}
              </p>
            )}
            {!statsLoading && !statsError && topCourses.length > 0 && (
              <ul className="flex flex-col divide-y divide-border" data-testid="adm-01-dashboard-top-courses">
                {topCourses.map((course) => (
                  <li
                    key={course.id}
                    className="flex items-center justify-between gap-4 py-3"
                    data-testid={`adm-01-dashboard-top-course-${course.id}`}
                  >
                    <span className="text-[14px] text-foreground">{course.title}</span>
                    <span className="text-[12px] font-medium text-muted-foreground">
                      {formatCount(course.studentCount)}
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}
